<script setup lang="ts">
import type { PagedResponse } from '~/types/api'; import type { WeakTopic } from '~/types/domain'
definePageMeta({ layout: 'app' }); useSeoMeta({ title: 'Weak topics' }); const api = useApi(); const { refreshTodayAndNavigation } = useLearningDataInvalidation(); const items = ref<WeakTopic[]>([]); const loading = ref(true); const recalculating = ref(false); const level = ref(''); async function load() { loading.value = true; try { items.value = (await api.get<PagedResponse<WeakTopic>>('/weak-topics', { level: level.value, page:1, pageSize:50 })).items } finally { loading.value = false } } async function recalculateAll() { recalculating.value = true; try { await api.post('/weak-topics/recalculate-all'); await Promise.all([load(), refreshTodayAndNavigation()]) } finally { recalculating.value = false } } watch(level,load); onMounted(load)
</script>
<template><div><CorePageHeader title="Weak topics" description="See the learning signals behind each weakness score."><UButton label="Recalculate all" icon="i-lucide-refresh-cw" :loading="recalculating" @click="recalculateAll" /></CorePageHeader><select v-model="level" class="filter"><option value="">All levels</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select><CoreLoadingState v-if="loading" label="Loading weak topics" /><CoreEmptyState v-else-if="!items.length" title="No weak topics detected" description="Profiles appear after enough review and practice signals exist." /><div v-else class="topics"><NuxtLink v-for="item in items" :key="item.profileId" :to="`/app/weak-topics/${item.profileId}`"><div><div class="meta"><CoreStatusBadge :value="item.level" /><span>{{ item.resourceType }}</span></div><h2>{{ item.resourceTitle }}</h2><p>{{ item.signalCount }} signals contribute to this profile.</p></div><strong>{{ item.score }}</strong></NuxtLink></div></div></template>
<style scoped>.filter { margin-bottom: 1rem; padding: .5rem; border: 1px solid var(--ui-border); border-radius: .5rem; }.topics { display: grid; grid-template-columns: repeat(auto-fill,minmax(18rem,1fr)); gap: .7rem; }.topics a { display: flex; justify-content: space-between; gap: 1rem; padding: 1rem; border: 1px solid var(--ui-border); border-radius: .75rem; }.topics a:hover { border-color: var(--ui-primary); }.meta { display: flex; align-items: center; gap: .5rem; color: var(--ui-text-muted); font-size: .75rem; }.topics h2 { margin: .6rem 0 .2rem; font-weight: 700; }.topics p { color: var(--ui-text-muted); font-size: .82rem; }.topics > a > strong { font-size: 1.5rem; }</style>
